window.onload = () => {                                         // window.onload = () => { ... }; - IIFE (Immediately Invoked Function Expression) - немедленно вызываемая функция. Это обработчик события, но по сути - функция обратного вызова (callback), которая выполняется сразу после загрузки страницы. Это защищает код от выполнения до готовности DOM. Функция-обработчик - код, который выполняется в ответ на событие (механизм, когда браузер говорит «страница готова»). Картинки и стили должны быть загружены, иначе слайдер может не найти элементы или показать пустой экран. Когда страница полностью загрузилась (картинки, стили и т.п.), запускаем слайдер.
    const slideTitles = [                                       // Литерал массива.
        'Роза Baronesse', 'Роза Aspirin Rose', 'Роза Red Piano', 'Роза Pink Piano', 'Роза Novalis', 
        'Роза Bonica', 'Роза Vanille Fraise', 'Роза Agnes Schilliger', 'Роза Piano', 'Роза Pastella', 
        'Роза Black Forest Rose', 'Роза Princesse Astrid', 'Роза Grand Prix', 'Роза Malibu', 'Роза Leonardo da Vinci',
        'Роза Pride and Prejudice', 'Роза Eddy Mitchell', 'Роза Lions-Rose', 'Роза Green Tea', 'Роза Coral Lions-Rose',
        'Роза Nina', 'Роза Spray white', 'Роза Cherry Parfait', 'Роза Princess Alexandra', 'Роза William Morris', 'Роза Brass Band',
        'Роза Lutea', 'Роза Maurice Utrillo', 'Роза Eliane Gillet’', 'Роза Benjamin Britten',
        'Роза Remy Martin ', 'Роза Graham Thomas', 'Роза Royal Amethyst', 'Роза The Countryman',
        'Роза Dame de Coeur', 'Роза Sugar Moon', 'Роза Caramella', 'Роза Baronne Prevost',
        'Роза Marilyn Monroe', 'Роза Hot Cocoa', 'Роза Easy Does It', 'Роза Golden Celebration',
        'Роза Charles de Gaulle', 'Роза Bull’s Eye', 'Роза Lady Emma Hamilton', 'Роза Plum Perfect',
        'Роза Michelangelo', 'Роза Candy Cane Cocktail', 'Роза Munstead Wood', 'Роза Yves Piaget'  
    ];                                                          // Создаем массив с заголовками для каждого слайда. Порядок строго соответствует порядку картинок в HTML.

    new Slider({                                                // Создаем слайдер: передаем ему, где искать картинки, кнопки и какие заголовки показывать.
        images: '.gallery .photo img',                          // Селектор для всех картинок в галерее. Где лежат все фото в HTML.
        next: '.gallery .tabs .next',                           // Селектор кнопки «Вперед». Где кнопка «Вперед» - input.next внутри .tabs.   
        prev: '.gallery .tabs .prev',                           // Селектор кнопки «Назад». Где кнопка «Назад» - input.prev внутри .tabs.
        titles: slideTitles                                     // Передаем массив заголовков внутрь слайдера, чтобы при переключении подставлять нужный текст - какие заголовки подставлять к каждому фото.  
    });
};                                                              

function Slider({ images, next, prev, titles = [] }) {          // Конструктор слайдера. Вызывается через new Slider(...), создает экземпляр объекта с нужными свойствами и методами. Деструктуризация объекта в параметрах - сразу вытаскиваем нужные поля function Slider({ images, next, prev, titles = [] }) {...} вместо принятия одного объекта и обращения к params.images.  
    // DOM элементы                                             // Свойства экземпляра (this). Сохраняем DOM-элементы как свойства объекта (this.*), чтобы они были доступны во всех методах экземпляра.
    this.images = document.querySelectorAll(images);            // Глобальный объект document (встроенный в браузер) - это глобальный объект (доступен везде), представляющий текущую HTML-страницу. Находим все картинки по переданному селектору и сохраняем в this.images как NodeList. NodeList - это список узлов (коллекция элементов), который веб-браузер возвращает при поиске элементов на странице через MDN Web Docs, например, с помощью метода document.querySelectorAll().                 
    this.btNext = document.querySelector(next);                 // Находим кнопку «Вперед» и сохраняем ссылку на нее.                
    this.btPrev = document.querySelector(prev);                 // Находим кнопку «Назад» и сохраняем ссылку.       
    this.titles = titles  || [];                                // Логический оператор ИЛИ (||) с присвоением (устаревший способ - лучше использовать ?? для null/undefined - this.titles = titles ?? [];, но ?? реагирует только на null и undefined — то есть на «значение вообще отсутствует», а || реагирует на всё falsy: undefined, null, false, 0, '', NaN). Присвоение со значением по умолчанию: titles = [] - если не передали — будет пустой массив. Сохраняем переданный массив заголовков в свойство экземпляра класса. Если заголовков нет - пустой список. Здесь || [] — это страховка: если obj.titles не передали, передали undefined, null или даже false, то в this.titles попадёт пустой массив [].            
    this.titleEl = document.getElementById('slideTitle');       // Находим в DOM элемент для вывода заголовка слайда по его id, чтобы менять текст при переключении.       
    this.soundCamera = document.getElementById('soundCamera');  // Ссылка на аудио «щелчок камеры» (для кнопки Home).                  
    this.soundButton = document.getElementById('soundButton');  // Ссылка на аудио «нажатие кнопки» (для Next/Prev).                 
    this.bgMusic = document.getElementById('bgMusic');          // Ссылка на фоновую музыку.        
    this.bgFlash = document.querySelector('.bg-flash');         // Элемент для вспышки на фоне всей страницы (вне смартфона). Нужен, чтобы запускать анимацию «вспышки» по краям страницы по требованию.           
                                                                // Замыкание (Closure) - "закрытые" переменные внутри конструктора. Внутренние функции (navigate, showSlide, updateTitle) запоминают переменные, объявленные в конструкторе (currentIndex, autoPlayInterval, this.images), даже после того, как конструктор завершил работу. Это - лексическое окружение. const navigate = (direction, silent = false) => {...} использует currentIndex, this.images, this.titles, const showSlide = (index) => {...} использует this.images и this.titleEl.  
    let currentIndex = 0;                                       // Инициализируем индекс текущего слайда. Начинаем с 0 — это первый слайд в массиве. В дальнейшем будем менять это значение при переключении вперёд/назад или автопереключении. 
    let autoPlayInterval = null;                                // Хранит идентификатор интервала (от setInterval), который отвечает за автопереключение слайдов. null означает, что автовоспроизведение сейчас выключено и таймер не запущен. Нужно, чтобы корректно останавливать автоплей через clearInterval(autoPlayInterval).
    let isPlaying = false;                                      // Флаг состояния (State flag) "играет ли музыка?", булевы переменные, которые хранят текущее состояние программы. Флаг состояния автовоспроизведения: true — слайд-шоу играет, false — на паузе или остановлено. Помогает синхронизировать UI («пользовательский интерфейс» - всё, что пользователь видит на экране и с чем может взаимодействовать, например, менять иконку кнопки «Play/Pause») и логику (не запускать второй таймер, если уже идёт автоплей).
    let isHovering = false;                                     // Флаг состояния (State flag) "наведён ли курсор?", булевы переменные, которые хранят текущее состояние программы. Флаг, отслеживающий, находится ли курсор мыши над областью слайд-шоу. Нужен, чтобы приостанавливать автовоспроизведение при наведении и подсвечивать кнопки управления или всплывающие подсказки только при наведении.  

    // Утилиты/вспомогательные функции (помогают делать повторяющиеся действия). Модульный подход / Разделение ответственности: playSound — звуки, showSlide — отображение слайда, navigate — логика переключения, startAutoPlay / stopAutoPlay — автоплей, triggerBgFlash — визуальные эффекты. Каждая делает одно дело — это Single Responsibility Principle (принцип единственной ответственности).
    const playSound = (type) => {                               // Стрелочная функция -  (Arrow functions), она не имеет своего this и берет его из внешнего контекста (из конструктора). Выбираем нужный аудиоэлемент в зависимости от типа звука:          
        const sound = type === 'camera' ? this.soundCamera : this.soundButton;  // 'camera' → звук срабатывания камеры (эффект вспышки/съёмки), // любой другой тип → звук нажатия кнопки.
        // Тернарный оператор (Ternary operator).Короткая запись if...else в одну строку: условие (type === 'camera'), если true (? this.soundCamera), если false (: this.soundButton;).  
        if (!sound) return console.error(`Аудиоэлемент ${type} не найден!`);    // Если нужный аудиоэлемент не инициализирован (равен null/undefined), выводим ошибку в консоль и прерываем выполнение функции.
        sound.currentTime = 0;                                  // Сбрасываем воспроизведение на начало трека. Это нужно, чтобы звук проигрывался с самого начала, даже если он уже частично звучал.
        sound.play().catch(e => console.warn(`Звук ${type} заблокирован:`, e)); // Обработка ошибок (try/catch через .catch()) - Ловим ошибки (например, браузер блокирует автовоспроизведение) и пишем предупреждение в консоль, не ломая выполнение скрипта. Запускаем воспроизведение звука. .catch() обрабатывает ситуацию, когда браузер блокирует автовоспроизведение звука (частая ситуация: звук можно запустить только по действию пользователя).
    };

    const updateTitle = () => {                                 // Стрелочная функция -  (Arrow functions), она не имеет своего this и берет его из внешнего контекста (из конструктора). Проверяем, что элемент для вывода заголовка существует в DOM и что массив заголовков не пустой — так избегаем лишних операций и ошибок. 
        if (this.titleEl && this.titles.length) {               // Устанавливаем текст заголовка: берём заголовок по текущему индексу. 
            this.titleEl.textContent = this.titles[currentIndex] || '';         // Обновляем текст на странице при смене слайда. Если для этого слайда заголовка нет (undefined), ставим пустую строку.
        }
    };

    const showSlide = (index) => {                              // Проходимся по всем картинкам-слайдам и убираем у них класс, отвечающий за видимость. Это нужно, чтобы не было сразу нескольких видимых слайдов.
        this.images.forEach(img => img.className = '');         // Метод forEach() (итерация по коллекции) - проходим по всем картинкам и убираем у них класс.
        this.images[index].className = 'shown';                 // Метод classList.add() - управление CSS-классами элемента. Добавляем класс 'shown' картинке с нужным индексом — она станет видимой.
        updateTitle();                                          // Обновляем заголовок под текущий слайд (вызываем функцию выше).
    };

    // Переключение слайдов
    const navigate = (direction, silent = false) => {           // «Тихий» режим (параметр silent) -  условное поведение через флаг. Переключение слайдов — функция для движения вперёд/назад 
        if (!silent) playSound('button');                       // Если режим «тихий» (silent = false), проигрываем звук нажатия кнопки.
        this.images[currentIndex].className = '';               // Сбрасываем все CSS-классы у текущего изображения. Это нужно, чтобы убрать старые анимации/стили (например, fade-in, active и т.п.) перед тем как переключиться на следующий/предыдущий слайд.
        currentIndex = (currentIndex + direction + this.images.length) % this.images.length;  // Зацикленный слайдер (математическая формула модуля) - гарантирует, что индекс всегда в пределах [0, length-1]. Вычисляем новый индекс слайда с учётом направления (direction). direction = 1 (вперёд) или -1 (назад). Формула (currentIndex + direction + this.images.length) % this.images.length гарантирует корректный переход через границы массива:
                                                                // - если мы на последнем слайде и идём вперёд — переходим на первый; - если на первом и идём назад — переходим на последний (зацикленный слайдер). Добавление this.images.length нужно, чтобы избежать отрицательных индексов при операции % в JavaScript.
        showSlide(currentIndex);                                // Отображаем слайд с новым индексом.           
        if (isHovering) updateSlideNumber();                    // Если курсор сейчас находится над областью слайд-шоу (isHovering === true), обновляем отображение номера слайда на экране телефона.                            
    };

    this.next = (silent) => navigate(1, silent);                // «Тихий» режим (параметр silent) -  условное поведение через флаг. Метод для перехода к предыдущему слайду.                             
    this.prev = (silent) => navigate(-1, silent);               // «Тихий» режим (параметр silent) -  условное поведение через флаг. Аналогично next, но с направлением -1.                                   

    // Автопрокрутка
    const startAutoPlay = () => {                               // Объявляем функцию startAutoPlay — она запускает автопереключение слайдов.
        stopAutoPlay();                                         // Сначала останавливаем любой уже запущенный автоплей. // Это нужно, чтобы не создать несколько параллельных интервалов.
        autoPlayInterval = setInterval(() => this.next(true), 3000);  // Функция setInterval() (интервал — автопереключение). Запускаем интервал: каждые 3000 мс (3 секунды) вызываем this.next(true). // Аргумент true означает «тихий» режим (silent): без звуков, лишних анимаций и т.п. // Результат setInterval (идентификатор интервала) сохраняем в переменную autoPlayInterval, чтобы потом можно было его остановить через clearInterval. 
    };

    const stopAutoPlay = () => {                                // Объявляем функцию stopAutoPlay — она останавливает автопереключение.
        if (autoPlayInterval) {                                 // Проверяем, есть ли сейчас активный интервал (переменная не null).
            clearInterval(autoPlayInterval);                    // Функция clearInterval() (остановка интервала). Останавливаем таймер по его идентификатору.
            autoPlayInterval = null;                            // Обнуляем переменную, чтобы чётко показать: автоплей сейчас не работает. Это важно для проверок в других местах кода (например, чтобы не останавливать дважды).
        }
    };

    // Музыка и автопрокрутка
    const toggleMusicAndAuto = () => {                          // Объявляем функцию toggleMusicAndAuto — она одновременно переключает воспроизведение фоновой музыки и автопереключение слайдов (вкл/выкл).
        if (!this.bgMusic) return console.warn('bgMusic не найден'); // Проверяем, существует ли элемент фоновой музыки (this.bgMusic). Если нет — выводим предупреждение в консоль и прерываем выполнение функции.
        
        if (!isPlaying) {                                       // Если музыка сейчас НЕ играет (isPlaying === false), значит, нужно включить музыку и запустить автоплей.
            this.bgMusic.play().catch(e => console.warn('Автовоспроизведение заблокировано:', e)); // Обработка ошибок (try/catch через .catch()). Пытаемся запустить воспроизведение. .catch нужен, потому что браузеры часто блокируют автовоспроизведение звука без взаимодействия пользователя. 
            startAutoPlay();                                    // Запускаем автопереключение слайдов.   
        } else {
            this.bgMusic.pause();                               // Если музыка уже играет — ставим её на паузу.
            stopAutoPlay();                                     // Останавливаем автопереключение слайдов.
        }
        isPlaying = !isPlaying;                                 // Переключаем флаг состояния: если было false → станет true, и наоборот.
    };

    // Эффекты
    const triggerBgFlash = () => {                              // Функция для запуска эффекта вспышки фона (имитация вспышки камеры/съёмки).
        if (!this.bgFlash) return;                              // Проверяем, существует ли элемент вспышки (this.bgFlash). Если нет — просто выходим из функции, чтобы не было ошибки.
        this.bgFlash.classList.remove('active');                // Метод classList.add() / .remove() - управление CSS-классами элемента. Удаляем класс 'active', который запускает CSS-анимацию вспышки.
        void this.bgFlash.offsetWidth;                          // «Трюк» для принудительного пересчёта макета: браузер сбрасывает анимацию, если мы сначала убираем класс, а потом сразу добавляем. void this.bgFlash.offsetWidth заставляет браузер «заметить» удаление класса до следующей строки — иначе анимация не перезапустится. Характерный прием для CSS-анимаций. 
        this.bgFlash.classList.add('active');                   // Метод classList.add() / .remove() - управление CSS-классами элемента. Снова добавляем класс 'active' — теперь анимация сработает заново.
        setTimeout(() => this.bgFlash?.classList.remove('active'), 600); // Функция setTimeout() (отложенное выполнение).Через 600 мс убираем класс, чтобы эффект вспышки закончился.  ?. — безопасная проверка: если элемента вдруг не будет, код не сломается.
    };

    const triggerScreenDim = () => {                            // Функция затемнения экрана телефона (эффект «засветки/затемнения» при съёмке).  
        const screen = document.querySelector('.phone-frame .screen'); // Ищем элемент экрана внутри рамки телефона по селектору.
        if (!screen) return console.error('.screen не найден!');       // Если элемент не найден — выводим ошибку в консоль и выходим. Это поможет быстро заметить проблему, если верстка изменилась.     
        screen.classList.add('screen-dim');                     // Добавляем класс, который затемняет экран (скорее всего, через opacity/filter в CSS).
        setTimeout(() => screen.classList.remove('screen-dim'), 600);  // Функция setTimeout() (отложенное выполнение). Через 600 мс убираем класс — экран возвращается к нормальному виду.
    };

    // Номер слайда
    const slideNumberEl = document.getElementById('slide-number');     // Находим элемент, где будет отображаться номер слайда (по id).   
    const slideContainer = document.querySelector('.gallery .photo');  // Находим контейнер слайдов.    
    const updateSlideNumber = () => {                                  // Функция обновления текста с номером слайда.
        if (slideNumberEl) {                                           // Обновляем текст только если элемент существует (защита от ошибок).
            slideNumberEl.textContent = `Слайд ${currentIndex + 1}`;   // Обновляем текст на странице при смене слайда - обновление пользовательского интерфейса (UI). currentIndex — это индекс массива (начинается с 0), поэтому +1.
        }
    };

    if (slideNumberEl && slideContainer) {                             // Если оба элемента найдены — вешаем обработчики событий на hover. Hover (наведение) - это состояние, когда курсор мыши находится над элементом.   
        slideContainer.addEventListener('mouseenter', () => {          // Событие mouseenter / mouseleave (наведение). При наведении мыши на контейнер слайда:
            isHovering = true;                                         // Помечаем, что курсор сейчас над слайдером.
            updateSlideNumber();                                       // Сразу обновляем номер слайда (чтобы он появился актуальным).
            slideNumberEl.style.opacity = '1';                         // Делаем номер видимым (opacity 1 — полностью непрозрачный).
        });
        slideContainer.addEventListener('mouseleave', () => {          // Событие mouseenter / mouseleave (наведение). При уходе курсора с контейнера:
            isHovering = false;                                        // Сбрасываем флаг наведения.
            slideNumberEl.style.opacity = '0';                         // Скрываем номер слайда (opacity 0 — полностью прозрачный).
        });
    }

    // Обработчики событий
    const titleToggle = document.getElementById('rosa-collection-toggle');    // Находим элемент кнопки переключения (по id).    
    titleToggle?.addEventListener('click', toggleMusicAndAuto.bind(this)) ||  // Обработчик событий (Event listeners). Метод .bind(this) (привязка контекста). Если элемент найден — вешаем на него обработчик клика. При клике вызываем toggleMusicAndAuto, но привязываем контекст (this), чтобы внутри функции this ссылался на экземпляр слайдера, а не на кнопку. Оператор ?. защищает от ошибки, если элемента нет. 
        console.error('Не найден элемент #rosa-collection-toggle');           // || console.error сработает, если addEventListener вернул falsy (например, элемента не было) — так сразу увидим в консоли, что кнопка не найдена.          

    this.btNext?.addEventListener('click', () => this.next());         // Обработчик событий (Event listeners). Оператор опциональной последовательности (Optional chaining - ?.): если this.btNext равен null или undefined — код не упадет, а просто вернет undefined - это защита от ошибок. На кнопку «Вперёд» (this.btNext) вешаем клик: при нажатии листаем вперёд. ?. — безопасная проверка: если кнопки нет, код не упадёт.
    this.btPrev?.addEventListener('click', () => this.prev());         // Обработчик событий (Event listeners). Аналогично для кнопки «Назад»: при клике листаем назад.

    const homeBtn = document.querySelector('.phone-frame .home-button');  // Ищем кнопку Home на макете телефона (внутри .phone-frame есть .home-button).
    homeBtn?.addEventListener('click', () => {                         // При клике на кнопку Home выполняем сразу три действия:
        playSound('camera');                                           // Воспроизводим звук «щёлчка камеры» (ты просил добавить управление музыкой и звуками).
        triggerBgFlash();                                              // Запускаем эффект фоновой вспышки (тот самый приём с перезапуском анимации). 
        triggerScreenDim();                                            // Затемняем экран смартфона — имитация эффекта съёмки/вспышки.    
    });

    // Клавиатура
    document.addEventListener('keydown', (e) => {                      // Глобальный слушатель клавиатуры (keydown). Вешаем глобальный обработчик события «нажатие клавиши» на весь документ. Это позволяет листать слайды с клавиатуры из любой точки страницы, даже если фокус не на конкретном элементе (актуально для твоего слайд‑шоу).  
        if (e.key === 'ArrowLeft') {                                   // Если нажата стрелка «Влево» — это переход к предыдущему слайду.
            e.preventDefault();                                        // Предотвращение стандартного поведения (e.preventDefault()). Отменяем стандартное поведение браузера (например, прокрутку страницы влево)  
            this.prev();                                               // Вызываем метод перехода назад.      
        } else if (['ArrowRight', ' ', 'Enter'].includes(e.key)) {     // Если нажата стрелка «Вправо», пробел или Enter — это переход вперёд.                 
            e.preventDefault();                                        // Предотвращение стандартного поведения (e.preventDefault()). Также отменяем стандартное действие (прокрутку, активацию элементов и т.п.).    
            this.next();                                               // Вызываем метод перехода вперёд.                  
        }
    });

    // Инициализация. При создании слайдера сразу показываем первый слайд, чтобы страница не была пустой.
    showSlide(0);                                                      // Это нужно, чтобы при загрузке страницы слайд‑шоу сразу отображал контент, а не оставался пустым до первого клика/нажатия.                                                        
}
